import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem114 preserva dados operacionais',()=>{for(const [n,titulo,expected,link] of [["7748620676","Perfume Árabe His Confession Masculino Original 100ML","Perfume masculino His Confession — 100 mL anunciados","https://www.mercadolivre.com.br/p/MLB78627840?wid=MLB7748620676"],["7752259240","Kit Internet Completo Antena Starlink Mini X 2 Suportes Cabo","Kit Starlink Mini com dois suportes e cabo anunciados","https://www.mercadolivre.com.br/p/MLB2110254597?wid=MLB7752259240"],["7870098964","Kit 3 Bonecos Marvel Hulk 22cm Homem Aranha 9cm Capitã 9cm","Kit anunciado com três bonecos: Hulk, Homem-Aranha e Capitã","https://www.mercadolivre.com.br/up/MLBU5617346059?pdp_filters=item_id%3AMLB7870098964"]]){const p={id:'mlMLB'+n,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,link:'https://produto.mercadolivre.com.br/MLB-123'}).titulo,titulo);}});
